<?php $rid=(int)($_GET['request']??0);$s=$pdo->prepare('SELECT r.*,b.full_name borrower,c.name category,(SELECT name FROM equipment WHERE id=r.equipment_id) equipment_name FROM loan_requests r JOIN borrowers b ON b.id=r.borrower_id JOIN equipment_categories c ON c.id=r.category_id WHERE r.id=?');$s->execute([$rid]);$r=$s->fetch();if(!$r||$r['status']!=='Approved')redirect('?page=requests');$error='';verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT id FROM loan_requests WHERE id=? AND status='Approved' FOR UPDATE");$s->execute([$rid]);if(!$s->fetch())throw new RuntimeException('Request is no longer approved.');$s=$pdo->prepare("SELECT i.id FROM equipment_items i JOIN equipment e ON e.id=i.equipment_id WHERE e.category_id=? AND (?=0 OR e.id=?) AND i.status='Available' AND i.condition_label IN ('Good','Fair') ORDER BY i.id LIMIT ? FOR UPDATE");$s->bindValue(1,$r['category_id'],PDO::PARAM_INT);$s->bindValue(2,(int)($r['equipment_id']??0),PDO::PARAM_INT);$s->bindValue(3,(int)($r['equipment_id']??0),PDO::PARAM_INT);$s->bindValue(4,(int)$r['quantity'],PDO::PARAM_INT);$s->execute();$items=$s->fetchAll();if(count($items)!==(int)$r['quantity'])throw new RuntimeException('Not enough matching items are currently available.');foreach($items as $item){$q=$pdo->prepare("UPDATE equipment_items SET status='On Loan' WHERE id=? AND status='Available'");$q->execute([$item['id']]);if(!$q->rowCount())throw new RuntimeException('An item is no longer available.');$q=$pdo->prepare('INSERT INTO loans(request_id,borrower_id,item_id,issued_by,issued_at,due_date) VALUES(?,?,?,?,NOW(),?)');$q->execute([$rid,$r['borrower_id'],$item['id'],user()['id'],$r['due_date']]);}$q=$pdo->prepare("UPDATE loan_requests SET status='Issued',reviewed_by=?,reviewed_at=NOW() WHERE id=?");$q->execute([user()['id'],$rid]);log_activity($pdo,'Issued equipment','request',$rid);$pdo->commit();flash('Equipment issued and loan records created.');redirect('?page=loans');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Could not complete issue transaction.';}}layout_start('Issue equipment','requests'); ?><div class="page-heading"><div><a class="back-link" href="?page=request-view&id=<?=$rid?>">← Request #<?=str_pad((string)$rid,4,'0',STR_PAD_LEFT)?></a><h1>Issue equipment</h1><p class="muted">Confirm the handover to <?=h($r['borrower'])?>.</p></div></div><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif; ?><section class="panel form-panel"><div class="callout"><strong><?=h($r['equipment_name']?:$r['category'])?></strong><span><?=$r['quantity']?> item(s) · expected return <?=date('j M Y',strtotime($r['due_date']))?></span></div><form method="post" onsubmit="return confirm('Issue the available items and create loan records?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><p class="muted">CareShare will select the required available physical items and create an individual loan for each one.</p><button class="button primary">Confirm issue</button> <a class="button ghost" href="?page=request-view&id=<?=$rid?>">Cancel</a></form></section><?php layout_end();
